Yeah, I had to add extra logging, basically the most interesting part is to log the error instead of returning it in migrate Get/Put sectino.

```diff
diff --git a/command/operator_migrate.go b/command/operator_migrate.go
index 2e956046f3..94874aaad3 100644
--- a/command/operator_migrate.go
+++ b/command/operator_migrate.go
@@ -251,6 +251,7 @@ func (c *OperatorMigrateCommand) migrateAll(ctx context.Context, from physical.B

                entry, err := from.Get(ctx, path)
                if err != nil {
+                       c.logger.Info("ERROR reading", "entry", entry, "err", err)
                        return fmt.Errorf("error reading entry: %w", err)
                }

@@ -259,6 +260,7 @@ func (c *OperatorMigrateCommand) migrateAll(ctx context.Context, from physical.B
                }

                if err := to.Put(ctx, entry); err != nil {
+                       c.logger.Info("ERROR writing", "entry", entry, "err", err)
                        return fmt.Errorf("error writing entry: %w", err)
                }
                c.logger.Info("copied key", "path", path)
```
